  s48: { t: 'Unternehmens-Marktplatz', x: 'Unternehmen von Spielern: <b>kaufen</b> oder tageweise <b>mieten</b>. Deins kannst du auch verkaufen oder vermieten. Ab Stufe 1.' },
  s49: { t: 'Kredit', x: 'Geld gegen dein Unternehmen als Pfand. Ein Teil der Einnahmen tilgt ihn selbst. 7 Tage keine Zahlung — Pfändung und Verkauf: abgezogen werden Kredit plus <b>doppelter Zins</b> (15 % → Kredit × 1,30), der Rest gehört dir. Ab Stufe 1.' },
  s50: { t: 'Aktivitätsregel', x: 'Die Stadt nimmt Unternehmen von Inaktiven. In beliebigen <b>{days} Tagen</b> <b>{bmin} Stk. kaufen</b> oder <b>{smin} Stk. verkaufen</b> — eins von beiden reicht.', bought: '🛒 Gekauft in {days} Tagen', sold: '📦 Verkauft in {days} Tagen', note: '3 Tage vor einer Pfändung erinnern wir dich im Spiel und in Telegram.', b: 'Verstanden' },
