  s54: { t: 'Partneraufgaben', x: 'Abos und Aktionen bei Partnern — für Bonus-$CITY.' },
  s55: { t: 'City Pass', x: 'Saison mit 30 Stufen. XP für Ziele, Schichten, Reparaturen, Verkäufe. Stufen bringen Booster, $CITY und Ressourcen.' },
  s56: { t: 'Chat', x: 'Der Chat aller Spieler und deiner Allianz. Hier werden Deals gemacht.' },
  s57: { t: 'Ligen', x: 'Jede Woche eine Gruppe gleich starker Spieler, Punkte für Aktivität und Verkäufe. Die Besten steigen auf: Bronze → Silber → Gold → Platin → Diamant. <b>‹ ›</b> — andere Ligen, <b>„Ganze Division“</b> — alle, Suche, Freunde.' },
  s58: { t: 'Allianzen', x: 'Teams: gemeinsame Kasse, Chat, Stufen. Beitreten jederzeit, gründen ab City-Pass-Stufe 5.' },
  s59: { t: 'Freunde', x: 'Empfehlungen sind auf <b>„Unternehmen“</b>: die Taste 👥 oben. Tippe sie: teile deinen Link und erhalte einen Teil der Steuer deiner Freunde.' },
  s60: { t: 'Einstellungen und Mitteilungen', x: 'Wähle Erinnerungen: Lager, Verschleiß, Preise, Schichtende. Ruhezeiten in der Nacht. Auch Sprache, Telegram-Bot und Intro-Stimme.' },
  s61: { t: 'Handbuch und Hilfe', x: 'Im Menü ☰ ist das <b>Handbuch</b> mit Antworten auf alles, und jeder Bildschirm außer «Unternehmen» hat eine <b>«?»</b>-Taste mit Artikeln dazu. Nichts gefunden – <b>Hilfe</b>: der Support-Chat; zuerst antwortet Willy GRAM, bei Bedarf ein Mensch.' },
